# Adapter Pattern Example
class OldSystem:
    def legacy_request(self):
        return "legacy payload"

class Adapter:
    def __init__(self, adaptee):
        self.adaptee = adaptee
    def request(self):
        return self.adaptee.legacy_request()

# Facade provides a ___ interface to a set of interfaces in a subsystem
class SmartHomeFacade:
    def goodnight(self):
        self.lights.off()
        self.locks.close()

class ComponentDecorator:
    def __init__(self, component):
        self.___ = component

class DynamicProxy:
    def __getattr__(self, name):
        # Intercept and forward call
        return getattr(self.___, name)
